fn task_operands_naive(sched: &Scheduler, last_a: usize) -> (usize, bool) {
    let a = sched.operand_a();
    let stage = sched.advance_ring(); // cursor marches; old stages overwritten
    load_gm_to_l1(a, stage); // ALWAYS: even a.addr == last_a
    (stage, false)
}

